const $=id=>document.getElementById(id);let draftReady=false;function resetApproval(){draftReady=false;$('approve').checked=false;$('export').disabled=true;if($('print'))$('print').disabled=true;}function route(){const h=location.hash.slice(1);const p=['report','receipts','project'].includes(h)?h:'home';document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==p+'-view');document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===p));}window.addEventListener('hashchange',route);route();
$('sample').onclick=()=>{resetApproval();$('org').value='Fictional Community Initiative';$('period').value='12–18 October 2026';$('notes').value='Held a digital-literacy workshop with 24 participants.\nDistributed 18 learning kits at that workshop.\nHeld a separate reading session with 12 attendances. These may include repeat participants; unique beneficiary total is not established.';$('challenges').value='Learning materials arrived late. Attendance at the reading session was lower than planned.';$('next').value='Confirm materials before the next workshop. Ask participants which session times work best.';location.hash='report';route();$('status').textContent='Fictional sample loaded. Prepare a draft to continue.';};
$('draft').onclick=()=>{resetApproval();const org=$('org').value.trim(),period=$('period').value.trim(),notes=$('notes').value.trim();if(!org||!period||notes.length<30){$('status').textContent='Add an organisation, reporting period and at least 30 characters of field notes.';return;}$('review').value=`WEEKLY DONOR REPORT\n${org}\nReporting period: ${period}\n\nACTIVITIES AND REPORTED COUNTS\n${notes}\n\nCHALLENGES\n${$('challenges').value.trim()||'Not provided — coordinator to confirm.'}\n\nNEXT STEPS\n${$('next').value.trim()||'Not provided — coordinator to confirm.'}\n\nREVIEW NOTES\nCounts above are reproduced from supplied notes, not independently verified. Do not add activity attendance counts to infer unique beneficiaries.\n\nPrepared with the local report organiser. No AI analysis performed.`;$('draft-area').hidden=false;$('empty-report').hidden=true;draftReady=true;$('status').textContent='Draft prepared. Check and edit every section before approving.';};
$('approve').onchange=()=>{const blocked=!($('approve').checked&&draftReady&&$('review').value.trim());$('export').disabled=blocked;$('print').disabled=blocked;};$('review').oninput=()=>{ $('approve').checked=false;$('export').disabled=true;$('print').disabled=true;};['org','period','notes','challenges','next'].forEach(id=>$(id).oninput=()=>{resetApproval();$('status').textContent='Inputs changed. Prepare a fresh draft before exporting.';});$('clear').onclick=()=>{['org','period','notes','challenges','next','review'].forEach(id=>$(id).value='');resetApproval();$('draft-area').hidden=true;$('empty-report').hidden=false;$('ai-consent').checked=false;$('status').textContent='Inputs cleared.';};$('export').onclick=()=>{if(!draftReady||!$('approve').checked||!$('review').value.trim())return;const u=URL.createObjectURL(new Blob([$('review').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='NGO-Approved-Report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('status').textContent='Approved report exported. Nothing was sent to donors.';};
let installPrompt;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('install').hidden=false;});$('install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('install').hidden=true;};window.addEventListener('appinstalled',()=>{$('install').hidden=true;});
function connectionStatus(){$('connection').hidden=navigator.onLine;}window.addEventListener('online',connectionStatus);window.addEventListener('offline',connectionStatus);connectionStatus();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{console.info('Offline installation unavailable in this browser.');});
window.addEventListener('beforeunload',event=>{if($('notes').value.trim()||$('review').value.trim()){event.preventDefault();event.returnValue='';}});

const safeText=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function snapshot(){return Object.fromEntries(['org','period','notes','challenges','next'].map(k=>[k,$(k).value.trim()]));}
let requestSequence=0;
$('ai-draft').onclick=async()=>{if(!$('ai-consent').checked){$('status').textContent='Confirm consent before sending notes to AI.';return;}const input=snapshot();if(!input.org||!input.period||input.notes.length<30){$('status').textContent='Add an organisation, period and at least 30 characters of notes.';return;}const sequence=++requestSequence;const before=JSON.stringify(input);resetApproval();$('draft-area').hidden=true;$('empty-report').hidden=false;$('ai-draft').disabled=true;$('draft').disabled=true;$('status').textContent='Preparing an AI draft. No report will be approved or sent automatically.';try{const r=await fetch('/api/report',{method:'POST',headers:{'Content-Type':'application/json'},body:before,signal:AbortSignal.timeout(65000)});const d=await r.json();if(sequence!==requestSequence||before!==JSON.stringify(snapshot())){$('status').textContent='Inputs changed. Request a fresh draft.';return;}if(!r.ok)throw Error(d.error||'AI drafting is unavailable.');if(!d.report||d.requires_review!==true)throw Error('Unexpected report response.');const parts=['WEEKLY DONOR REPORT',input.org,'Reporting period: '+input.period];for(const[k,title]of [['activities','ACTIVITIES'],['challenges','CHALLENGES'],['next_steps','NEXT STEPS']]){parts.push('\n'+title);parts.push(...d.report[k].map(x=>x.summary+'\nSource: “'+x.source_quote+'”'));if(!d.report[k].length)parts.push('Not provided — coordinator to confirm.');}parts.push('\nCOORDINATOR REVIEW',...d.report.warnings,'Quotes and numeric tokens checked automatically; semantic accuracy is not guaranteed. Verify every claim. Unique beneficiaries must not be inferred from summed attendance.');$('review').value=parts.join('\n');$('draft-label').textContent='AI DRAFT / HUMAN REVIEW REQUIRED';$('draft-area').hidden=false;$('empty-report').hidden=true;draftReady=true;$('status').textContent='AI draft ready. Review evidence and approve only after checking facts.';}catch(e){$('status').textContent=e.name==='TimeoutError'?'The AI request timed out. Try again or organise locally.':e.message;}finally{$('ai-draft').disabled=false;$('draft').disabled=false;}};
const clearAction=$('clear').onclick;$('clear').onclick=()=>{requestSequence++;clearAction();};const sampleAction=$('sample').onclick;$('sample').onclick=()=>{requestSequence++;sampleAction();};const localAction=$('draft').onclick;$('draft').onclick=()=>{requestSequence++;$('draft-label').textContent='LOCAL DRAFT / NOT APPROVED';localAction();};
$('print').onclick=()=>{if(!draftReady||!$('approve').checked)return;const w=window.open('','_blank');if(!w){$('status').textContent='Allow the print window to save a PDF.';return;}w.opener=null;w.document.write('<!doctype html><html><title>Approved NGO Report</title><style>body{font:12pt/1.6 Georgia,serif;margin:20mm;white-space:pre-wrap;overflow-wrap:anywhere}@page{size:A4;margin:16mm}body{margin:0}</style><body>'+safeText($('review').value)+'</body></html>');w.document.close();w.focus();w.print();};
